questionvariables.text:
/* ---- Base triangle ABC ---- */
Ax : -3; Ay : 1;
Bx : -1; By : 4;
Cx :  2; Cy : 2;

/* ---- Mode: 0 = rotation (congruent), 1 = not congruent ---- */
mode : rand(2);

/* ---- Rotation data: angle and a safe integer centre keeping both triangles on grid ---- */
/* curated (angle, ox, oy) triples, each verified to stay within the window */
rotdata : [
    [90,  -1, -4], [90,  5, 5], [90,  5, 4],
    [180,  3,  0], [180, 2, -1], [180, 3, 4],
    [270, -1, -4], [270, 2, -3], [270, 4, -1]
];
pick : rotdata[rand(length(rotdata)) + 1];
ang : pick[1];
ox  : pick[2];
oy  : pick[3];

/* rotate a point [x,y] about (ox,oy) by ang degrees, anticlockwise (ang in {90,180,270}) */
rotpt(px, py) := block([dx, dy],
    dx : px - ox, dy : py - oy,
    if ang = 90  then [ox - dy, oy + dx]
    elseif ang = 180 then [ox - dx, oy - dy]
    else [ox + dy, oy - dx]
);

/* ---- Build the image triangle ---- */
if mode = 0 then (
    imA : rotpt(Ax, Ay),
    imB : rotpt(Bx, By),
    imC : rotpt(Cx, Cy),
    Sx : imA[1], Sy : imA[2],
    Tx : imB[1], Ty : imB[2],
    Vx : imC[1], Vy : imC[2]
) else (
    /* NOT congruent: stretch by factor 2 in the y-direction, then shift.
       Side lengths change, so this is not an isometry. */
    sh : rand(3) + 2,
    Sx : Ax + sh, Sy : 2*Ay - 1,
    Tx : Bx + sh, Ty : 2*By - 1,
    Vx : Cx + sh, Vy : 2*Cy - 1
);

/* ---- Congruence flag ---- */
is_cong : if mode = 0 then true else false;

/* ---- Centre coordinates passed to the JSXGraph figure (capitalised names
   because the figure references {#Ox#}, {#Oy#}). In the not-congruent case the
   centre is not meaningful, so we just mark a neutral on-grid point. ---- */
Ox : if mode = 0 then ox else 0;
Oy : if mode = 0 then oy else 0;

/* ---- Part (a): Yes/No dropdown ---- */
ta_cong_opts : [
    ["Yes, they are congruent", is_cong],
    ["No, they are not congruent", not is_cong]
];

/* ---- Part (b): name the transformation ---- */
ta_trans : if mode = 0 then "rotation" else "none";
ta_trans_opts : [
    ["Rotation", is(ta_trans = "rotation")],
    ["Reflection", false],
    ["Translation", false],
    ["None of the above", is(ta_trans = "none")]
];

/* ---- Part (c): centre (typed) and angle (dropdown) ---- */
/* teacher's centre; for the non-congruent case any point is accepted (see PRT) */
ta_centre : if mode = 0 then [ox, oy] else [ox, oy];
ta_angle_opts : [
    ["90 degrees", mode = 0 and ang = 90],
    ["180 degrees", mode = 0 and ang = 180],
    ["270 degrees", mode = 0 and ang = 270],
    ["Not applicable",  mode = 1]
];

/* ---- Text used in the worked solution ---- */
sol_text : if mode = 0
    then sconcat("The two triangles have equal side lengths and the same orientation, so they are congruent. ",
                 "Triangle \\(ABC\\) maps onto \\(A'B'C'\\) by a rotation of ", string(ang),
                 "\\(^\\circ\\) anticlockwise about the centre \\(O = (", string(ox), ",\\ ", string(oy), ")\\).")
    else "The image has been stretched in the vertical direction, so its side lengths are not equal to those of the original. Distances are not preserved, therefore the two figures are not congruent and no single rigid transformation maps one onto the other.";

/* ---- helper values for question tests (must live in questionvariables) ---- */
qt_cong_right : mcq_correct(ta_cong_opts)[1];
/* the wrong congruence option is simply the opposite Yes/No string */
qt_cong_wrong : if is_cong then "No, they are not congruent" else "Yes, they are congruent";
qt_trans_right : mcq_correct(ta_trans_opts)[1];
qt_angle_right : mcq_correct(ta_angle_opts)[1];

feedbackvariables.text:
/* For rotations, the centre must match exactly. For the non-congruent case,
   the centre is not meaningful, so we only require the angle dropdown to say
   "Not applicable" and we accept any centre entry. */
centre_ok : is(ans3 = ta_centre);
angle_ok  : is(ans4 = mcq_correct(ta_angle_opts)[1]);
